ST.xhtml:p:
IF LimitLogic THEN
  IF Ton_In THEN
    Ton_Filter2(IN:= FALSE);
    Ton_Filter(IN:= Ton_In,PT:=FilterTime);
    IF Ton_Filter.Q THEN
      Ton_Out:=TRUE;
    END_IF; 
  ELSE
    Ton_Filter(IN:= FALSE);
    Ton_Filter2(IN:= NOT Ton_In,PT:=FilterTime);
    IF Ton_Filter2.Q THEN
      Ton_Out:=FALSE;
    END_IF;    
  END_IF;  
ELSE  
  IF Ton_In THEN
    Ton_Filter2(IN:= FALSE);
    Ton_Filter(IN:= Ton_In,PT:=FilterTime);
    IF Ton_Filter.Q THEN
      Ton_Out:=FALSE;
    END_IF; 
  ELSE
    Ton_Filter(IN:= FALSE);
    Ton_Filter2(IN:= NOT Ton_In,PT:=FilterTime);
    IF Ton_Filter2.Q THEN
      Ton_Out:=TRUE;
    END_IF;    
  END_IF;  
END_IF;
